class Solution {
public:
    int getSum(int a, int b) {
        int ans = 0, bit = 0;
        for (int i = 0; i < 32; i++) {
            int x = (a >> i) & 1, y = (b >> i) & 1;
            if (x & y) {
                ans |= (bit << i);
                bit = 1;
            } else if (x | y) {
                ans |= (1 ^ bit) << i;
            } else {
                ans |= (bit << i);
                bit = 0;
            }
        }
        return ans;
    }
};

